// C0 core careers: occupations replace the 4 legacy tracks (behind the `occ` flag; new lives in the app turn it on).
// Table: src/content/occupations.json (generated by tools/occupations.py from tools/careers-draft.csv). Every number is
// 推估 (design estimate) until L1 wires ILOSTAT (CC BY 4.0) / TW MOL (OGDL-1) / US BLS (PD) data. Illicit numbers stay 推估.
// Equity: entry odds use only country income group, era, education, quintile, urban/rural, sex (ILOSTAT-style probability
// weight, never a gate) and stats — never ethnicity, caste, religion or name region.
import table from '../../content/occupations.json' with { type: 'json' };
import iloOcc from '../../../public/data/l1/ilostat-occ.json' with { type: 'json' };
import type { Edu } from '../economy/household.ts';
import type { Sex } from '../data/types.ts';

export type Group = 'agri' | 'trades' | 'services' | 'professional' | 'public' | 'special' | 'startup' | 'illicit' | 'status';
export interface Drivers { from?: number; pre?: number; sex?: 'M' | 'F'; rural?: number; urban?: number; coastal?: number; lowQ?: number; highQ?: number; smart?: number; social?: number; twn?: number; rare?: number; space?: number; young?: number }
export interface Occ { id: string; zh: string; en: string; isco: string; group: Group; rel: number; est: boolean; ladder: [string, number][]; edu: Edu | 'none'; drv: Drivers; risk: { unemp: number; mort: number; early?: number }; to: string[]; src: string }
export const OCCS: Occ[] = (table as unknown as { occupations: Occ[] }).occupations;
const BY = new Map(OCCS.map((o) => [o.id, o]));
export const occById = (id: string | undefined): Occ | undefined => (id ? BY.get(id) : undefined);

export type IncomeGroup = 'L' | 'LM' | 'UM' | 'H';
/** PPP GDP per capita thresholds (推估 proxy for the World Bank income groups) */
export const incomeGroup = (gdpPc: number): IncomeGroup => (gdpPc < 4000 ? 'L' : gdpPc < 12000 ? 'LM' : gdpPc < 25000 ? 'UM' : 'H');
export const ENTRY_GROUPS: Group[] = ['agri', 'trades', 'services', 'professional', 'public', 'special'];
/** 推估 employment structure by income group (targets for the mix guardrail until L1 delivers ILOSTAT shares) */
export const GROUP_TARGET: Record<IncomeGroup, Record<string, number>> = {
  L: { agri: 0.55, trades: 0.17, services: 0.2, professional: 0.04, public: 0.035, special: 0.005 },
  LM: { agri: 0.35, trades: 0.22, services: 0.27, professional: 0.09, public: 0.065, special: 0.005 },
  UM: { agri: 0.15, trades: 0.27, services: 0.3, professional: 0.18, public: 0.095, special: 0.005 },
  H: { agri: 0.04, trades: 0.22, services: 0.32, professional: 0.31, public: 0.105, special: 0.005 },
};
/** calibration weights (推估): education gates and transitions shift the realised mix, so group draw odds are scaled so the
 *  realised working-age mix matches GROUP_TARGET (fitted by tools/c0-calibrate.test.ts; refit when tables change) */
export const GROUP_ADJ: Record<IncomeGroup, Record<string, number>> = {
  L: { agri: 1.0, trades: 0.631, services: 0.961, professional: 3.5, public: 5, special: 1.089 },
  LM: { agri: 1.019, trades: 0.697, services: 0.91, professional: 2.3, public: 1.9, special: 1.379 },
  UM: { agri: 0.959, trades: 0.883, services: 0.997, professional: 1.196, public: 1.23, special: 0.473 },
  H: { agri: 0.878, trades: 0.8, services: 0.84, professional: 1.0, public: 1.055, special: 0.863 },
};
const EDU_RANK: Record<string, number> = { none: 0, primary: 1, secondary: 2, vocational: 2, tertiary: 3, graduate: 4 };
export const eduOk = (o: Occ, plan: Edu) => EDU_RANK[plan]! >= EDU_RANK[o.edu]!;
/** reachable only through rare transitions, never a direct entry draw */
export const RARE_ROLES = ['local_rep', 'legislator', 'minister', 'astronaut'];
export const SPACE = ['USA', 'RUS', 'CHN', 'JPN', 'FRA', 'DEU', 'ITA', 'GBR', 'ESP', 'NLD', 'BEL', 'SWE', 'CAN'];
/** 推估 sex weight where the draft cites a sex skew — used ONLY when the country has no ILOSTAT sex×ISCO data (never a gate) */
export const SEX_W = 1.5;
/** L1: ILOSTAT employment by sex × ISCO-08/88 major group (CC BY 4.0, public/data/l1/ilostat-occ.json). The entry weight of an
 *  occupation in major group m for sex s is P(m | s) / P(m) for the country at the nearest decade with data — a probability
 *  weight that reproduces the observed occupational sex mix, clamped to [SEXW_MIN, SEXW_MAX]; never a gate. Groups the source
 *  merges or omits (both sexes 0) get weight 1. Countries without ILOSTAT data fall back to the 推估 SEX_W rule. */
type IloCell = { y: number; cls: string; M: number[]; F: number[] };
const ILO = (iloOcc as unknown as { data: Record<string, Record<string, IloCell>> }).data;
export const SEXW_MIN = 0.25, SEXW_MAX = 4;
/** analysis switch for the equity check only (tools/l1/equity.test.ts): 'ilo' = data weights (default), 'neutral' = no sex weight */
export const OCC_OPTS: { sexMode: 'ilo' | 'neutral' } = { sexMode: 'ilo' };
export function iloCell(iso: string, year: number): IloCell | undefined {
  const c = ILO[iso]; if (!c) return undefined;
  let best: string | undefined; for (const d of Object.keys(c)) if (best === undefined || Math.abs(+d - year) < Math.abs(+best - year)) best = d;
  return best === undefined ? undefined : c[best];
}
export function iloSexWeight(isco: string, sex: Sex, iso: string, year: number): number | undefined {
  const c = iloCell(iso, year); const m = Number(isco[0]); if (!c || !/^\d/.test(isco)) return undefined;
  const all = c.M[m]! + c.F[m]!; if (all <= 0) return 1;
  const tot = c[sex].reduce((a, b) => a + b, 0); if (tot <= 0) return 1;
  return Math.min(SEXW_MAX, Math.max(SEXW_MIN, (c[sex][m]! / tot) / all));
}

/** the only inputs entry odds may use (equity: no ethnicity / caste / religion / region) */
export interface EntryCtx { iso: string; year: number; gdp: number; plan: Edu; quintile: number; urban: boolean; sex: Sex; age: number; smart: number; social: number }
export function occWeight(o: Occ, x: EntryCtx): number {
  if (!ENTRY_GROUPS.includes(o.group) || RARE_ROLES.includes(o.id) || !eduOk(o, x.plan)) return 0;
  const d = o.drv; let w = 1;
  if (d.from && x.year < d.from) return 0;
  if (d.space && !SPACE.includes(x.iso)) return 0;
  if (d.pre && x.year >= d.pre) w *= 0.3;
  if (d.rare) w *= d.rare === 1 ? 0.06 : d.rare === 2 ? 0.006 : 0;
  const sw = OCC_OPTS.sexMode === 'neutral' ? 1 : iloSexWeight(o.isco, x.sex, x.iso, x.year);
  if (sw !== undefined) w *= sw; else if (d.sex) w *= d.sex === x.sex ? SEX_W : 1 / SEX_W;
  if (d.rural) w *= x.urban ? 0.4 : 2;
  if (d.urban && !d.rural) w *= x.urban ? 1.5 : 0.6;
  if (d.lowQ) w *= x.quintile <= 2 ? 1.6 : 0.7;
  if (d.highQ) w *= x.quintile >= 4 ? 1.6 : 0.7;
  if (d.smart) w *= 0.4 + x.smart / 80;
  if (d.social) w *= 0.4 + x.social / 80;
  if (d.twn && x.iso === 'TWN') w *= d.twn;
  if (d.young && x.age >= 30) w *= 0.2;
  return w;
}
/** two-stage entry draw: group by the national structure (renormalised over groups this person can enter), then occupation */
export function entryDraw(x: EntryCtx, u1: number, u2: number): string {
  const ig = incomeGroup(x.gdp); const tgt = GROUP_TARGET[ig];
  const byG = ENTRY_GROUPS.map((g) => { const os = OCCS.filter((o) => o.group === g).map((o) => [o.id, occWeight(o, x)] as const).filter(([, w]) => w > 0); return { g, os, p: os.length ? tgt[g]! * GROUP_ADJ[ig][g]! : 0 }; });
  const tot = byG.reduce((a, b) => a + b.p, 0);
  let acc = 0; let pick = byG.find((b) => b.os.length)!;
  for (const b of byG) { acc += b.p / tot; if (u1 < acc && b.os.length) { pick = b; break; } }
  const wt = pick.os.reduce((a, [, w]) => a + w, 0); let a2 = 0;
  for (const [id, w] of pick.os) { a2 += w / wt; if (u2 < a2) return id; }
  return pick.os.at(-1)![0];
}
/** wage normaliser per income group: target-weighted mean of rel × typical rung (so the employment-weighted mean wage ≈ legacy) */
/** income calibration per income group (推估; fitted by tools/c0/calibrate.test.ts so mean lifetime income ≈ legacy engine) */
export const NORM_K: Record<IncomeGroup, number> = { L: 1.2995, LM: 1.1546, UM: 1.0273, H: 1.159 };
export const WAGE_NORM: Record<IncomeGroup, number> = Object.fromEntries((['L', 'LM', 'UM', 'H'] as IncomeGroup[]).map((ig) => {
  let s = 0; for (const g of ENTRY_GROUPS) { const os = OCCS.filter((o) => o.group === g && !RARE_ROLES.includes(o.id) && !o.drv.rare); s += GROUP_TARGET[ig][g]! * os.reduce((a, o) => a + o.rel * o.ladder[0]![1], 0) / Math.max(1, os.length); }
  return [ig, s * NORM_K[ig]];
})) as Record<IncomeGroup, number>;
/** mortality normaliser: employment-weighted mean occupational hazard = 1 (risk is reallocated, not added) */
export const MORT_NORM: Record<IncomeGroup, number> = Object.fromEntries((['L', 'LM', 'UM', 'H'] as IncomeGroup[]).map((ig) => {
  let s = 0; for (const g of ENTRY_GROUPS) { const os = OCCS.filter((o) => o.group === g && !o.drv.rare); s += GROUP_TARGET[ig][g]! * os.reduce((a, o) => a + o.risk.mort, 0) / Math.max(1, os.length); }
  return [ig, s];
})) as Record<IncomeGroup, number>;
export const occHazard = (id: string | undefined, gdp: number, age: number): number => {
  const o = occById(id); if (!o || age < 18 || age > 64) return 1;
  const m = ILLICIT[o.id]?.mort ?? o.risk.mort;
  return o.group === 'illicit' ? m * (age <= 35 ? 1 : 0.7) : m / MORT_NORM[incomeGroup(gdp)];
};
/** wage factor of an occupation at rung r (rel × ladder / norm); startups use their own luck draw on top */
/** per-country normalising term (推估, fitted by tools/c0/ratios.test.ts): within an income group, countries differ in how
 *  education, quintile and drivers co-move with occupation, so mean lifetime income under C0 can drift from the pre-C0
 *  engine. Key ISO; missing keys → 1. v0.9.0 rc4: fitted on the mean over 20 seed sets × N=200, 1970 + 1990 cohorts (tools/c0/multiseed.test.ts). Refit whenever the occupation table, GROUP_ADJ or NORM_K change. */
export const COUNTRY_K: Record<string, number> = { IND: 0.9997, NGA: 1.1045, BRA: 1.0887, TWN: 0.9875, USA: 0.9808, DEU: 0.9847, KOR: 0.9449, CHN: 1.0053, ETH: 0.9363, MEX: 1.11, IDN: 1.079 };
export function occWageF(id: string, rung: number, gdp: number, plan?: Edu, iso?: string): number {
  const o = occById(id); if (!o) return 1;
  const r = Math.max(0, Math.min(rung, o.ladder.length - 1));
  const ig = incomeGroup(gdp);
  return (o.rel * o.ladder[r]![1]) / (plan ? eduNorm(ig, plan) * NORM_K[ig] : WAGE_NORM[ig]) / (iso ? COUNTRY_K[iso] ?? 1 : 1);
}
/** expected entry rel × first rung for a person with this education in this income group (the normalising term c,
 *  taken per education tier so occupations reallocate wages without double-counting the education premium) */
const EN = new Map<string, number>();
export function eduNorm(ig: IncomeGroup, plan: Edu): number {
  const key = ig + plan; const hit = EN.get(key); if (hit) return hit;
  let s = 0, ps = 0;
  for (const g of ENTRY_GROUPS) {
    const os = OCCS.filter((o) => o.group === g && !RARE_ROLES.includes(o.id) && !o.drv.rare && eduOk(o, plan)); if (!os.length) continue;
    const p = GROUP_TARGET[ig][g]! * GROUP_ADJ[ig][g]!; ps += p; s += p * os.reduce((a, o) => a + o.rel * o.ladder[0]![1], 0) / os.length;
  }
  const v = ps > 0 ? s / ps : 1; EN.set(key, v); return v;
}
export const maxRung = (id: string | undefined) => Math.max(0, (occById(id)?.ladder.length ?? 1) - 1);

// ---- legacy tracks → closest occupation (old saves continue in the occupation system)
export function legacyOcc(track: string, plan: Edu, gdp: number): string {
  const hi = EDU_RANK[plan]! >= 3;
  switch (track) {
    case 'stable': return hi ? 'civil_servant' : 'office_clerk';
    case 'informal': return gdp < 12000 ? 'informal_vendor' : 'construction_lab';
    case 'startup': return hi ? 'studio_su' : 'food_retail_su';
    default: return hi ? 'sales_rep' : EDU_RANK[plan]! >= 2 ? 'office_clerk' : 'factory_op';
  }
}

// ---- startups (推估 survival shaped on US BLS Business Employment Dynamics, public domain)
export type Biz = 'food_retail_su' | 'studio_su' | 'franchise_su' | 'tech_su';
export const BIZ: Record<Biz, { capital: number; surv: Record<number, number>; sigma: number }> = {
  food_retail_su: { capital: 1, surv: { 1: 0.8, 3: 0.5, 5: 0.35 }, sigma: 0.6 },
  studio_su: { capital: 0.3, surv: { 3: 0.55 }, sigma: 0.7 },
  franchise_su: { capital: 1.5, surv: { 3: 0.65 }, sigma: 0.35 },
  tech_su: { capital: 0.5, surv: { 3: 0.4, 5: 0.25 }, sigma: 0.8 },
};
/** yearly hazard in business year y (1-based), piecewise-constant between the curve's anchor points */
export function bizHazard(t: Biz, y: number): number {
  const pts = Object.entries(BIZ[t].surv).map(([k, v]) => [Number(k), v] as const).sort((a, b) => a[0] - b[0]);
  let prevY = 0, prevS = 1;
  for (const [yy, s] of pts) { if (y <= yy) return 1 - (s / prevS) ** (1 / (yy - prevY)); prevY = yy; prevS = s; }
  const [ly, ls] = pts.at(-1)!; const [py, ps] = pts.length > 1 ? pts.at(-2)! : [0, 1];
  return 1 - (ls / ps) ** (1 / (ly - py));
}
/** tech exits within the first 5 years: acquihire 8%, acquisition 3%, IPO 0.3% (推估) → yearly probabilities */
export const TECH_EXIT = { acquihire: [0.0165, 2], acquisition: [0.006, 10], ipo: [0.0006, 50] } as const;

// ---- illicit (design content, 推估; consequences only; auto-choice always refuses)
export const ILLICIT: Record<string, { arrest: number; mort: number }> = {
  loan_shark: { arrest: 0.15, mort: 1.5 }, gang: { arrest: 0.2, mort: 3 }, scam_ring: { arrest: 0.3, mort: 1.5 }, illegal_gambling: { arrest: 0.15, mort: 1.3 },
};
export const PRISON_PENALTY = 0.8;

// ---- rare transitions (推估 yearly probabilities; caps are tested)
export const RARE_PATHS: { to: string; from: string[]; p: number; social?: number; space?: boolean }[] = [
  { to: 'local_rep', from: ['lawyer', 'journalist', 'civil_servant', 'pm_mgr', 'sales_rep', 'teacher'], p: 5e-6, social: 60 },
  { to: 'legislator', from: ['local_rep'], p: 0.002 },
  { to: 'minister', from: ['legislator'], p: 0.005 },
  { to: 'astronaut', from: ['pilot', 'military_officer', 'professor'], p: 2e-5, space: true },
];
/** occupation name in the UI language (ja/ko/vi fall back to English until L1) */
export const occName = (id: string | undefined, lang: string) => { const o = occById(id); return !o ? '' : lang === 'zh-TW' ? o.zh : o.en; };

/** C0 save migration: a pre-v0.9.0 save (no occ flag) continues in the occupation system from the age it resumes at,
 *  so the replayed years stay byte-identical and only the future uses occupations */
export function migrateSaveCfg<C extends { occ?: boolean; occFrom?: number }>(cfg: C, years: number): C {
  return cfg.occ || cfg.occFrom !== undefined ? cfg : { ...cfg, occFrom: years };
}
